后序遍历判定每棵子树是否为完全二叉树。对每个结点，递归获取左子树和右子树的信息（大小、是否完全、是否满），然后根据完全二叉树的定义判定当前子树。

```cpp
#include <bits/stdc++.h>
using namespace std;
const int N = 100005;
int n, l[N], r[N], ans;
struct Info {
    int sz;      // 子树大小
    bool full;   // 是否为满二叉树
    bool complete; // 是否为完全二叉树
};
Info dfs(int u) {
    if (u == 0) return {0, true, true};
    Info L = dfs(l[u]), R = dfs(r[u]);
    Info cur;
    cur.sz = L.sz + R.sz + 1;
    // 满二叉树：左右子树都是满的且大小相等
    cur.full = L.full && R.full && L.sz == R.sz;
    // 完全二叉树判定
    if (L.full && R.full && L.sz == R.sz) cur.complete = true;
    else if (L.full && R.complete && L.sz == R.sz) cur.complete = true;
    else if (L.complete && R.full && L.sz == R.sz + 1) cur.complete = true;
    else cur.complete = false;
    if (cur.complete) ans++;
    return cur;
}
int main() {
    cin >> n;
    for (int i = 1; i <= n; i++) cin >> l[i] >> r[i];
    dfs(1);
    cout << ans << endl;
    return 0;
}
```

递归判断两棵子树是否互为镜像。两个结点互为镜像的条件是：值相等，且A的左子树与B的右子树互为镜像，A的右子树与B的左子树互为镜像。

```cpp
#include <bits/stdc++.h>
using namespace std;
struct Node {
    int val, left, right;
} tree[1005];
bool isMirror(int a, int b) {
    if (a == 0 && b == 0) return true;
    if (a == 0 || b == 0) return false;
    return tree[a].val == tree[b].val &&
           isMirror(tree[a].left, tree[b].right) &&
           isMirror(tree[a].right, tree[b].left);
}
int main() {
    int n; cin >> n;
    for (int i = 1; i <= n; i++) {
        cin >> tree[i].val >> tree[i].left >> tree[i].right;
    }
    cout << (isMirror(tree[1].left, tree[1].right) ? "YES" : "NO") << endl;
    return 0;
}
```
